// Each mount starts an interval and returns a cleanup, like useEffect.
const timers = new Set();

function mount(withCleanup) {
  const id = setInterval(() => {}, 1000);
  timers.add(id);
  return () => {
    if (withCleanup) {
      clearInterval(id);
      timers.delete(id);
    }
  };
}

for (let i = 0; i < 3; i++) mount(false)();
for (let i = 0; i < 3; i++) mount(true)();
console.log(timers.size);
for (const id of timers) clearInterval(id);

const cache = new Map();
function getUser(id) {
  if (!cache.has(id)) cache.set(id, { id, data: new Array(1000).fill(0) });
  return cache.get(id);
}

const lru = new Map();
function getLimited(id) {
  if (lru.has(id)) {
    const v = lru.get(id);
    lru.delete(id);
    lru.set(id, v);
    return v;
  }
  lru.set(id, { id });
  if (lru.size > 10) lru.delete(lru.keys().next().value);
  return lru.get(id);
}

for (let i = 0; i < 500; i++) getUser(i % 50);
for (let i = 0; i < 500; i++) getLimited(i % 50);
console.log(cache.size, lru.size);

